      for (i = 0; i < pairs.length; i++) s += pairs[i][1];
      var x = r() * s;
      for (i = 0; i < pairs.length; i++) { x -= pairs[i][1]; if (x <= 0) return pairs[i][0]; }
      return pairs[pairs.length - 1][0];
