/* 和音の色を感情で染める（根音と機能は変えない） */
function emoColor(chs, kind, rng) {
  var i, out = [];
  for (i = 0; i < chs.length; i++) {
    var c = { root: chs[i].root, q: chs[i].q, b: chs[i].b };
    var q = c.q;
    if (kind === "sharp") {
      if (q === "dom7" || q === "dom9") c.q = rng.chance(0.45) ? "dom7alt" : (rng.chance(0.4) ? "dom7b9" : q);
      else if (q === "maj7") c.q = rng.chance(0.3) ? "maj7s11" : q;
      else if (q === "m7") c.q = rng.chance(0.25) ? "m7b5" : q;
    } else if (kind === "dark") {
      if (q === "maj7" || q === "maj6") c.q = rng.chance(0.25) ? "maj7s11" : q;
      else if (q === "m7" || q === "m6") c.q = rng.chance(0.5) ? "m9" : (rng.chance(0.3) ? "mMaj7" : q);
      else if (q === "dom7" || q === "dom9") c.q = rng.chance(0.4) ? "dom7b9" : q;
    } else if (kind === "warm") {
      if (q === "maj7") c.q = rng.chance(0.45) ? "maj69" : q;
      else if (q === "m7") c.q = rng.chance(0.5) ? "m9" : q;
      else if (q === "dom7") c.q = rng.chance(0.45) ? "dom13" : (rng.chance(0.3) ? "dom9" : q);
    } else if (kind === "bright") {
      if (q === "maj7") c.q = rng.chance(0.55) ? "maj69" : q;
      else if (q === "dom7") c.q = rng.chance(0.5) ? "dom9" : (rng.chance(0.4) ? "dom13" : q);
      else if (q === "m7") c.q = rng.chance(0.3) ? "m9" : q;
    } else if (kind === "soft") {
      if (q === "dom7alt" || q === "dom7b9") c.q = rng.chance(0.5) ? "dom9" : q;
      else if (q === "maj7") c.q = rng.chance(0.35) ? "maj69" : q;
      else if (q === "m7") c.q = rng.chance(0.4) ? "m9" : q;
    }
    out.push(c);
  }
  return out;
}

