/* 語法の好みで音階を寄せる */
function biasScale(sc, ch, bias) {
  var i, out = sc.slice();
  function has(x) { return out.indexOf(x) >= 0; }
  function add(x) { if (!has(x)) out.push(x); }
  function del(x) { var k = out.indexOf(x); if (k >= 0) out.splice(k, 1); }
  if (bias === "blues") {
    /* ブルーノート（♭3・♭5）を足し、変化音は使わない（古いスウィングの耳） */
    if (isDom(ch.q)) out = [0, 2, 3, 4, 5, 7, 9, 10];
    else if (isMin(ch.q)) out = [0, 2, 3, 5, 6, 7, 9, 10];
    else out = [0, 2, 3, 4, 5, 7, 9, 11];
  } else if (bias === "diatonic") {
    /* 素直な音階：半音の飾りをほとんど使わない */
    if (isDom(ch.q)) out = [0, 2, 4, 5, 7, 9, 10];
    else if (isMin(ch.q)) out = [0, 2, 3, 5, 7, 9, 10];
    else out = [0, 2, 4, 5, 7, 9, 11];
  } else if (bias === "lydpenta") {
    /* リディアン寄り＋5音音階の骨格 */
    if (!isMin(ch.q) && !isDom(ch.q)) { del(5); add(6); }
    if (isDom(ch.q)) { del(5); add(6); add(2); }
    if (isMin(ch.q)) { add(2); add(9); }
  } else if (bias === "melmin") {
    /* メロディック・マイナー系に置き換える */
    if (isDom(ch.q)) out = [0, 2, 4, 6, 7, 9, 10];
    else if (isMin(ch.q)) out = [0, 2, 3, 5, 7, 9, 11];
    else out = [0, 2, 4, 6, 8, 9, 11];
  } else if (bias === "symmetric") {
    if (isDom(ch.q)) out = [0, 1, 3, 4, 6, 7, 9, 10];
    else if (isMin(ch.q)) out = [0, 2, 3, 5, 7, 8, 11];
  } else if (bias === "dim") {
    /* ジャンゴ：ドミナントは♭9、マイナーは6thを効かせる */
    if (isDom(ch.q)) { add(1); add(3); del(2); }
    if (isMin(ch.q)) { add(9); del(10); }
  } else if (bias === "bach") {
    out = baroqueScale(ch);
  } else if (bias === "djent") {
    out = djentScale(ch);
  } else if (bias === "wa") {
    if (WA_SC) out = waPcs(ch);
  } else if (bias === "modal") {
    if (isMin(ch.q)) out = [0, 2, 3, 5, 7, 9, 10];
    else if (isDom(ch.q)) out = [0, 2, 5, 7, 9, 10];
    else out = [0, 2, 4, 6, 7, 9, 11];
  } else if (bias === "corea") {
    out = coreaScale(ch);
  } else if (bias === "classical") {
    out = classScale(ch);
  } else if (bias === "neo") {
    out = neoScale(ch);
  } else if (bias === "phrygian") {
    if (isDom(ch.q)) out = [0, 1, 4, 5, 7, 8, 10];
  } else if (bias === "hmin") {
    /* ディ・メオラ：ドミナントはフリジア・ドミナント、マイナーはハーモニック・マイナー、長和音はリディアン */
    if (isDom(ch.q)) out = [0, 1, 4, 5, 7, 8, 10];
    else if (isMin(ch.q)) out = [0, 2, 3, 5, 7, 8, 11];
    else out = [0, 2, 4, 6, 7, 9, 11];
  }
  out.sort(function (a, b) { return a - b; });
  return out;
}
/* 着地音の好み */
function landPc(kind, ch) {
  if (kind === "six") return isMin(ch.q) ? [9, 3] : [9, 4];
  if (kind === "nine") return [2, 4];
  if (kind === "third") return guidePcs(ch);
  if (kind === "blue") return isMin(ch.q) ? [3, 0] : [3, 10, 0];
  if (kind === "root") return [0, 7];
  if (kind === "tension") return isDom(ch.q) ? [13, 6, 8] : [2, 6, 9];
  return guidePcs(ch);
}

