  if (tech.entropy) { var et = 2.6 + R.f() * 0.9; voices = voices.map(function (v) { return ctEntropyControl(R, v, et, C.pcs); }); used.push("エントロピー制御（目標 " + et.toFixed(1) + " bit）"); }
  if (tech.isorhythm && voices[0] && total >= 20) { voices[0] = ctIsorhythm(R, voices[0], [2, 1, 1, 3, 1], q); used.push("アイソリズム（タレア 2-1-1-3-1）"); }
  if (tech.stretto && voices.length >= 2) { voices = ctStretto(R, voices, ctPool(C.pcs, ai[0].lo, ai[0].hi), total, q); used.push("ストレット（頂点）"); }
  if (tech.chaconne && voices.length >= 2 && total >= 20) {
    var bi = ai.filter(function (i) { return i.lo <= 48; })[0] || ai[ai.length - 1], cv = ctChaconne(R, bi, C.pcs, total, q), bvi = voices.reduce(function (b, v, i) { return (v[0] && v[0].inst === bi) ? i : b; }, -1);
    if (cv.length && bvi >= 0) { voices[bvi] = voices[bvi].concat(cv).sort(function (a, b) { return a.t - b.t; }); used.push("シャコンヌの低音（" + bi.jp + "）"); }
  }
  if (tech.metricmod) {
    var mm = [{ at: total * 0.18, ratio: 1.25 }, { at: total * 0.46, ratio: 0.80 }, { at: total * 0.70, ratio: 1.15 }, { at: total * 0.85, ratio: 1.40 }];
    voices = voices.map(function (v) { return ctMetricMod(v, mm); }); used.push("拍子の変換");
  }
  if (tech.polymeter && voices.length >= 3) {
    var met = [1.0, 0.75, 1.25, 0.875], vv;
    for (vv = 2; vv < voices.length; vv++) {
      var ms = met[vv % met.length], ts = voices[vv].length ? voices[vv][0].t : 0;
      voices[vv] = voices[vv].map(function (n) { return ctClone(n, { t: Math.max(0, ts + (n.t - ts) * ms), d: n.d * ms }); });
    }
    used.push("ポリメーター（内声部）");
  }
  if (tech.hocket && voices.length >= 2) { voices = ctHocket(voices, ai, 0.68, 0.82, total); used.push("ホケット（結の前半）"); }
  if (tech.echo && voices.length >= 2 && voices[1]) {
    var eN = voices[1].filter(function (n) { var p = n.t / total; return p >= 0.18 && p < 0.30; }), ec = ctEcho(R, eN, q * 0.5, 0.45, total);
    var eo = ec.filter(function (n) { return n.echo; });
    voices[1] = voices[1].concat(eo).sort(function (a, b) { return a.t - b.t; }); used.push("エコー");
  }
  if (tech.morph) { var altP = ctOp({ t: "T", n: 6 }, C.pcs); voices = voices.map(function (v) { return ctMorph(R, v, C.pcs, altP, 0.25, 0.35, total); }); used.push("スペクトル・モーフィング（三全音へ）"); }
  if (tech.cycle && ai.length >= 2 && total >= 20 && voices.length >= 2) {
    var ci = ai[Math.floor(ai.length * 0.5)], cyv = ctCycleVoice(R, ci, C.pcs, total, q, 3);
    if (cyv.length) { voices[1] = voices[1].concat(cyv).sort(function (a, b) { return a.t - b.t; }); used.push("音程サイクル（短3度）"); }
  }
  if (tech.stochorch && ai.length >= 2) { voices = ctStochOrch(R, voices, ai, total); used.push("確率的な管弦楽法（頂点）"); }
