  if (tech.additive && ai.length >= 1) { extra = extra.concat(ctAdditive(R, ai, shared, S, C.pcs)); used.push("加算的な変化"); }
  if (tech.micropoly && ai.length >= 3) { extra = extra.concat(ctMicropoly(R, voices, ai, S)); used.push("ミクロポリフォニー"); }
  if (tech.cluster) { extra = extra.concat(ctCluster(R, ai, S)); used.push("トーン・クラスター（頂点）"); }
