/* おすすめテンポ（1拍＝1マトラ／分）：ゆったり・中庸・軽快。シャクティ型は密度が高いので少し速め */
var IN_TEMPO = { 1: [48, 66, 56, "ゆったり（ヴィランビット寄り・アーラープを長く）"], 2: [64, 92, 76, "中庸（マディヤ・ライ）"], 3: [90, 130, 104, "軽快（ドゥルト寄り）"] };
function inTempoOf(r) {
  var c = IN_TEMPO[(r && r.tmp) || 2] || IN_TEMPO[2], b = (r && r.bpm) || c[2];
  return [Math.max(40, Math.round(b * 0.85)), Math.round(b * 1.2), b, c[3]];
}
/* ラーガの調性の性格：3度（長3度＝4／短3度＝3）で分ける。長調／短調の選択ではなく、ラーガが音階を決める */
function inCharKey(r) {
  var M = r.notes.indexOf(4) >= 0, m = r.notes.indexOf(3) >= 0;
  return (M && m) ? "both" : M ? "major" : m ? "minor" : "none";
}
